//! `git.ssh.*`: the SSH git transport of `forge serve` (M4 C13,
//! ADR-0032). Off by default; validated at load time like every other key
//! (`FG-SYS-0002`).
//!
//! - `git.ssh.enabled` (default `false`): start the SSH listener.
//! - `git.ssh.bind` (default `127.0.0.1:2224`): `host:port` it listens on.
//! - `git.ssh.host_key_file` (absolute path; required when enabled): the
//!   server's Ed25519 host key in OpenSSH format, made once with `forge
//!   admin ssh host-key generate` (never generated by `forge serve`: the
//!   key users pin must not change by accident).
//! - `git.ssh.clone_host` (optional, `host[:port]`): what clone URLs show
//!   (`ssh://git@<clone_host>/…`); default the host of `web.base_url`
//!   with the port of `git.ssh.bind`.
//! - `git.ssh.max_connections` (default 64), `git.ssh.max_connections_per_peer`
//!   (default 8, at most `max_connections`),
//!   `git.ssh.connections_per_minute_per_peer` (default 60),
//!   `git.ssh.auth_failures_per_minute_per_peer` (default 20): the
//!   connection bounds (`FG-GIT-0035`).
//! - `git.ssh.auth_timeout_ms` (default 30 s): a connection that has not
//!   authenticated by then is closed.
//! - `git.ssh.max_auth_attempts` (default 6, at most 20): public-key
//!   attempts per connection.
//! - `git.ssh.inactivity_timeout_ms` (default 10 min, at least
//!   `git.http.idle_timeout_ms` — checked across sections): no SSH packet
//!   in either direction for this long closes the connection.

use std::path::PathBuf;
use std::time::Duration;

use forge_errors::ForgeError;

use super::{database, invalid, millis, positive, valid_bind};

/// The key of the switch (named by errors and doctor).
pub const ENABLED_KEY: &str = "git.ssh.enabled";
/// The key of the host key file.
pub const HOST_KEY_FILE_KEY: &str = "git.ssh.host_key_file";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct GitSshConfig {
    pub enabled: bool,
    pub bind: String,
    pub host_key_file: Option<PathBuf>,
    pub clone_host: Option<String>,
    pub max_connections: u32,
    pub max_connections_per_peer: u32,
    pub connections_per_minute_per_peer: u32,
    pub auth_failures_per_minute_per_peer: u32,
    pub auth_timeout: Duration,
    pub max_auth_attempts: u32,
    pub inactivity_timeout: Duration,
}

impl Default for GitSshConfig {
    fn default() -> Self {
        Self {
            bind: Self::DEFAULT_BIND.to_owned(),
            ..Self::DEFAULT
        }
    }
}

impl GitSshConfig {
    /// The built-in defaults (`bind` is [`Self::DEFAULT_BIND`]: a `String`
    /// cannot be built in a const).
    pub const DEFAULT: GitSshConfig = GitSshConfig {
        enabled: false,
        bind: String::new(),
        host_key_file: None,
        clone_host: None,
        max_connections: 64,
        max_connections_per_peer: 8,
        connections_per_minute_per_peer: 60,
        auth_failures_per_minute_per_peer: 20,
        auth_timeout: Duration::from_secs(30),
        max_auth_attempts: 6,
        inactivity_timeout: Duration::from_secs(600),
    };
    /// The default `git.ssh.bind`.
    pub const DEFAULT_BIND: &'static str = "127.0.0.1:2224";
    /// The most public-key attempts one connection may make.
    pub const MAX_AUTH_ATTEMPTS_LIMIT: u32 = 20;

    pub(super) fn load<'a>(
        get: impl Fn(&str) -> Option<&'a str> + Copy,
    ) -> Result<Self, ForgeError> {
        let d = Self::DEFAULT;
        let ms = |t: Duration| u32::try_from(t.as_millis()).unwrap_or(u32::MAX);
        let text = |key: &'static str| match get(key).map(str::trim) {
            Some("") => Err(invalid(key, "empty")),
            other => Ok(other),
        };
        let enabled = match text(ENABLED_KEY)? {
            None | Some("false") => false,
            Some("true") => true,
            Some(_) => return Err(invalid(ENABLED_KEY, "invalid")),
        };
        let bind = text("git.ssh.bind")?.unwrap_or(Self::DEFAULT_BIND);
        if !valid_bind(bind) {
            return Err(invalid("git.ssh.bind", "invalid"));
        }
        let host_key_file = text(HOST_KEY_FILE_KEY)?
            .map(|p| database::password_path(HOST_KEY_FILE_KEY, p))
            .transpose()?;
        if enabled && host_key_file.is_none() {
            return Err(invalid(HOST_KEY_FILE_KEY, "missing"));
        }
        let clone_host = text("git.ssh.clone_host")?.map(str::to_owned);
        if let Some(host) = clone_host.as_deref() {
            if !valid_clone_host(host) {
                return Err(invalid("git.ssh.clone_host", "invalid"));
            }
        }
        let cfg = Self {
            enabled,
            bind: bind.to_owned(),
            host_key_file,
            clone_host,
            max_connections: positive(get, "git.ssh.max_connections", d.max_connections)?,
            max_connections_per_peer: positive(
                get,
                "git.ssh.max_connections_per_peer",
                d.max_connections_per_peer,
            )?,
            connections_per_minute_per_peer: positive(
                get,
                "git.ssh.connections_per_minute_per_peer",
                d.connections_per_minute_per_peer,
            )?,
            auth_failures_per_minute_per_peer: positive(
                get,
                "git.ssh.auth_failures_per_minute_per_peer",
                d.auth_failures_per_minute_per_peer,
            )?,
            auth_timeout: millis(get, "git.ssh.auth_timeout_ms", ms(d.auth_timeout))?,
            max_auth_attempts: positive(get, "git.ssh.max_auth_attempts", d.max_auth_attempts)?,
            inactivity_timeout: millis(
                get,
                "git.ssh.inactivity_timeout_ms",
                ms(d.inactivity_timeout),
            )?,
        };
        if cfg.max_connections_per_peer > cfg.max_connections {
            return Err(invalid("git.ssh.max_connections_per_peer", "above_max"));
        }
        if cfg.max_auth_attempts > Self::MAX_AUTH_ATTEMPTS_LIMIT {
            return Err(invalid("git.ssh.max_auth_attempts", "above_max"));
        }
        Ok(cfg)
    }

    /// The port of `bind` (validated at load time; 0 only for a test's
    /// ephemeral bind).
    pub fn port(&self) -> u16 {
        self.bind
            .rsplit_once(':')
            .and_then(|(_, p)| p.parse().ok())
            .unwrap_or(0)
    }
}

/// `host` or `host:port`: letters, digits, `.`, `-`, a bracketed IPv6
/// address; at most 253 characters, a port 1..=65535.
fn valid_clone_host(value: &str) -> bool {
    if value.is_empty() || value.len() > 253 {
        return false;
    }
    let (host, port) = if let Some(rest) = value.strip_prefix('[') {
        match rest.split_once(']') {
            Some((v6, "")) => (v6, None),
            Some((v6, tail)) => match tail.strip_prefix(':') {
                Some(p) => (v6, Some(p)),
                None => return false,
            },
            None => return false,
        }
    } else {
        match value.split_once(':') {
            Some((h, p)) => (h, Some(p)),
            None => (value, None),
        }
    };
    let host_ok = !host.is_empty()
        && host
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'.' || b == b'-' || b == b':');
    let port_ok = port.is_none_or(|p| p.parse::<u16>().is_ok_and(|n| n > 0));
    host_ok && port_ok
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used)]
    use super::*;

    fn load(pairs: &[(&str, &str)]) -> Result<GitSshConfig, ForgeError> {
        GitSshConfig::load(|k| pairs.iter().find(|(key, _)| *key == k).map(|(_, v)| *v))
    }

    fn reason(err: &ForgeError) -> (String, String) {
        let get = |k: &str| {
            err.context()
                .iter()
                .find(|(key, _)| *key == k)
                .map(|(_, v)| v.clone())
                .unwrap_or_default()
        };
        (get("config_key"), get("reason"))
    }

    #[test]
    fn off_by_default_with_the_documented_bounds() {
        let cfg = load(&[]).unwrap();
        assert!(!cfg.enabled);
        assert_eq!(cfg.bind, GitSshConfig::DEFAULT_BIND);
        assert_eq!(cfg.port(), 2224);
        assert_eq!(cfg.max_connections, 64);
        assert_eq!(cfg.max_connections_per_peer, 8);
        assert_eq!(cfg.auth_timeout, Duration::from_secs(30));
        assert_eq!(GitSshConfig::default().bind, GitSshConfig::DEFAULT_BIND);
    }

    #[test]
    fn enabled_needs_an_absolute_host_key_file() {
        let err = load(&[("git.ssh.enabled", "true")]).unwrap_err();
        assert_eq!(
            reason(&err),
            (HOST_KEY_FILE_KEY.to_owned(), "missing".to_owned())
        );
        let err = load(&[
            ("git.ssh.enabled", "true"),
            ("git.ssh.host_key_file", "relative/key"),
        ])
        .unwrap_err();
        assert_eq!(reason(&err).1, "not_absolute");
        let abs = if cfg!(windows) {
            r"C:\forge\ssh_host_ed25519_key"
        } else {
            "/etc/forge/ssh_host_ed25519_key"
        };
        let cfg = load(&[
            ("git.ssh.enabled", "true"),
            ("git.ssh.host_key_file", abs),
            ("git.ssh.bind", "0.0.0.0:22"),
        ])
        .unwrap();
        assert!(cfg.enabled);
        assert_eq!(cfg.port(), 22);
    }

    #[test]
    fn invalid_values_name_their_key() {
        for (pairs, key, why) in [
            (
                vec![("git.ssh.enabled", "yes")],
                "git.ssh.enabled",
                "invalid",
            ),
            (vec![("git.ssh.bind", "2222")], "git.ssh.bind", "invalid"),
            (
                vec![("git.ssh.max_connections", "0")],
                "git.ssh.max_connections",
                "zero",
            ),
            (
                vec![
                    ("git.ssh.max_connections", "4"),
                    ("git.ssh.max_connections_per_peer", "5"),
                ],
                "git.ssh.max_connections_per_peer",
                "above_max",
            ),
            (
                vec![("git.ssh.max_auth_attempts", "21")],
                "git.ssh.max_auth_attempts",
                "above_max",
            ),
            (
                vec![("git.ssh.clone_host", "a b")],
                "git.ssh.clone_host",
                "invalid",
            ),
            (
                vec![("git.ssh.clone_host", " ")],
                "git.ssh.clone_host",
                "empty",
            ),
        ] {
            let err = load(&pairs).unwrap_err();
            assert_eq!(reason(&err), (key.to_owned(), why.to_owned()), "{pairs:?}");
        }
    }

    #[test]
    fn clone_hosts() {
        for ok in [
            "git.example.test",
            "git.example.test:2222",
            "10.0.0.5",
            "[::1]:22",
        ] {
            assert!(valid_clone_host(ok), "{ok}");
        }
        for bad in [
            "",
            "git example",
            "host:0",
            "host:x",
            "[::1",
            "a/b",
            "host:22:33",
        ] {
            assert!(!valid_clone_host(bad), "{bad}");
        }
    }
}
